from pathlib import Path
import re
root=Path(__file__).resolve().parent
def shell(title,body,scripts='',render=False):
    return '<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>'+title+' · ChatSkins design</title>'+('<link rel="stylesheet" href="../css/skin-render.css">' if render else '')+'<link rel="stylesheet" href="round9.css"></head><body><a class="skip" href="#main">Skip to content</a>'+body+scripts+'</body></html>'
brand='<a class="brand" href="home9-mockup.html"><img src="chatskins-mark.svg" alt="">ChatSkins<span style="color:#38BDF8">.</span></a>'
nav='<header class="wrap nav">'+brand+'<nav aria-label="Main"><a href="skins9-mockup.html">Skins</a><a href="editor9-mockup.html">Customize</a><a href="docs-mockup.html">Docs</a><a href="request9-mockup.html">Request</a></nav><a class="button primary" href="editor9-mockup.html">Make my overlay</a></header>'
footer='<footer class="wrap footer"><div>'+brand+'<p>Made for the people in your chat.</p></div><nav aria-label="Footer"><a href="docs-mockup.html#privacy-safety">Privacy & safety</a><a href="docs-mockup.html#changelog">Changelog</a><a href="request9-mockup.html">Request a skin</a></nav><span>Free to make it yours.</span></footer>'
def preview(id,cls=''):
    return '<div class="preview '+cls+'" data-skin="'+id+'" aria-label="Sample chat preview"></div>'
floating=''
for n,(id,name) in enumerate([('guild-chat','Guild Chat'),('chatskins-signature','Signature'),('retro-rpg','Retro RPG'),('bubble-lift','Bubble Lift')],1):
    floating+='<div class="float-card f'+str(n)+'"><header>'+name+'<span>↗</span></header>'+preview(id)+'</div>'
features=[('◈','Game-style skins','From guild windows to crisp HUDs. Give your community a place in your world.'),('⌘','A full editor','Type, frames, spacing, and motion. Tune the details while chat stays in view.'),('≋','MMO chat channels','Officer, says, yells. Turn familiar Twitch roles into game-style conversation.'),('✦','Your favorite emotes','Twitch, 7TV, BTTV, and FFZ. Keep the expressions your community knows.'),('♧','Alerts that belong','Give stream moments a look that lives comfortably beside your chat.'),('⇄','Chat-powered skins','Let viewers choose the look. You choose the skins, permissions, and pace.'),('▧','Made for gameplay','Transparent backgrounds put the conversation right into your scene.'),('⌁','Safe, read-only chat','Show the conversation without giving the ordinary overlay posting permissions.')]
featurehtml=''.join('<article class="feature"><div class="icon" aria-hidden="true">'+icon+'</div><h3>'+title+'</h3><p>'+copy+'</p></article>' for icon,title,copy in features)
home='''<div class="announcement"><a href="docs-mockup.html#chat-powered-skins"><span>✦</span> New: chat-powered skins: let your viewers change your chat</a></div>'''+nav+'''<main id="main" class="wrap"><section class="hero"><div class="hero-copy"><span class="eyebrow"><i></i> PRESS START. MAKE IT YOURS.</span><h1>Your stream chat,<br><span class="gradient">skinned.</span></h1><p>Turn the conversation into part of your world.<br>42 expressive skins. Every detail yours. One link to go live.</p><div class="actions"><a class="button primary" href="editor9-mockup.html">Make my overlay <span aria-hidden="true">↗</span></a><a class="button" href="skins9-mockup.html">Browse 42 skins</a><a class="button" href="docs-mockup.html">Read the docs</a></div><p class="trust">Free · No login · One link · Works in OBS, Streamlabs, Twitch Studio, XSplit, Meld, vMix</p></div><div class="collage"><div class="floor"></div><div class="monitor"><div class="monitor-top"><span>YOUR STREAM / YOUR WORLD</span><span class="live"><i></i> LIVE PREVIEW</span></div><div class="screen"><div class="screen-caption">THE NEXT ADVENTURE<strong>Better with<br>your party.</strong></div>'''+preview('chatskins-signature','central-preview')+'''</div><div class="monitor-foot"><span id="active-skin">ChatSkins Signature · Featured</span><button id="pause-preview" aria-pressed="false">Pause previews</button></div></div>'''+floating+'''</div></section><div class="stats" aria-label="ChatSkins at a glance">'''+''.join('<div class="stat-tile"><strong>'+n+'</strong><span>'+label+'</span></div>' for n,label in [('42','SKINS. YOUR KIND OF DIFFERENT.'),('0','LOGINS NEEDED'),('1','LINK FOR OBS'),('100%','FREE. ALL YOURS.')])+'''</div><section class="section"><div class="section-title"><div><span class="eyebrow">BUILT AROUND YOUR CHAT</span><h2>A small overlay.<br>A lot of personality.</h2></div><p>Your community already has a voice.<br>Give it a look that feels at home on your stream.</p></div><div class="features">'''+featurehtml+'''</div></section><section class="works" aria-label="Compatible streaming apps"><p>Works with <strong style="color:white">anything with a Browser Source.</strong></p><div class="badges">'''+''.join('<span>'+a+'</span>' for a in ['OBS Studio','Streamlabs Desktop','Twitch Studio','XSplit','Meld Studio','vMix','Lightstream'])+'''</div></section><section class="section setup"><div><span class="eyebrow">FROM PICKED TO LIVE</span><h2>Meet your new<br><span class="gradient">Browser Source.</span></h2><p>No plugins to install. Works in OBS Studio, Streamlabs, Twitch Studio, XSplit, Meld and any app with a browser/web source.</p><a class="button primary" href="docs-mockup.html#streaming-apps">Open the setup guide</a></div><ol><li>Add a Browser Source</li><li>Paste your overlay URL</li><li>Set 1920×1080<br><small style="color:#A6B6CD">Or 1280×720 for a 720p canvas</small></li><li>Place ChatSkins above your game capture</li></ol></section><section class="section faq"><span class="eyebrow">A FEW GOOD QUESTIONS</span><h2>Before you press go live.</h2>'''+''.join('<details><summary>'+q+'</summary><p>'+a+'</p></details>' for q,a in [('Is it really free?','Yes. All 42 skins and ordinary chat overlay setup are free. No login is required.'),('Will it work with my streaming app?','If it supports a Browser Source or web source, you can add your overlay URL. The docs cover dimensions and source settings.'),('Can I change everything later?','Yes. Open the editor, adjust your look, then copy the new link into your Browser Source.'),('Does ChatSkins post in my chat?','Ordinary chat is read-only. It displays messages and does not send chat or moderate viewers.')])+'''</section><p class="review-note">Round 9 design preview · Alerts and audience controls are proposed features; verify integrations before publishing this announcement.</p></main>'''+footer
(root/'home9-mockup.html').write_text(shell('Your stream chat, skinned',home,'<script type="module" src="round9-previews.js"></script>',True),encoding='utf-8')
gallery=nav+'''<main id="main" class="wrap"><div class="page-head"><span class="eyebrow"><i></i> THE SKIN COLLECTION</span><h1>Find your <span class="gradient">chat energy.</span></h1><p>42 original looks. Live previews. Every one is yours to customize.</p></div><div style="display:flex;align-items:center;justify-content:space-between;gap:16px"><p id="gallery-count" role="status">Loading skins…</p><button class="button" id="pause-preview" aria-pressed="false">Pause previews</button></div><div class="filters" id="filters" aria-label="Skin groups"></div><div class="gallery-layout"><section class="gallery" id="gallery" aria-label="Live skin previews"></section><aside class="inspector" aria-label="Selected skin"><span class="eyebrow">YOUR STARTING POINT</span><h2 id="selected-name">ChatSkins Signature</h2><p id="selected-description"></p><div id="selected-preview" class="preview"></div><div id="scores"></div><a class="button primary" id="use-selected" href="editor9-mockup.html">Make my overlay</a><a class="button" id="customize-selected" href="editor9-mockup.html">Customize this skin</a><p style="font-size:11px">Free · No login needed<br>Make it yours in a few small changes.</p></aside></div><section class="section"><h2>Something else in mind?</h2><p>Tell us the look your community is missing.</p><a class="button" href="request9-mockup.html">Request a skin</a></section></main>'''+footer
(root/'skins9-mockup.html').write_text(shell('Find your chat energy',gallery,'<script type="module" src="round9-previews.js"></script>',True),encoding='utf-8')
docs='''<header class="doc-top"><div class="wrap nav"><button class="mobile-menu" id="doc-menu" aria-expanded="false" aria-controls="doc-sidebar" aria-label="Open documentation navigation">☰</button>'''+brand+'''<input class="search" id="doc-search" type="search" placeholder="Search documentation…" aria-label="Search documentation titles and headings" aria-controls="search-results"><a class="button" href="editor9-mockup.html">Make my overlay</a><div class="search-results" id="search-results" aria-label="Search results" hidden></div></div></header><div class="docs-layout"><aside class="sidebar" id="doc-sidebar" aria-label="Documentation navigation"></aside><main class="doc-article" id="main" tabindex="-1"></main><aside class="toc" id="doc-toc" aria-label="On this page"></aside></div>'''
(root/'docs-mockup.html').write_text(shell('Documentation',docs,'<script src="docs-content-index.js"></script><script src="round9-docs.js"></script>'),encoding='utf-8')

# Preserve existing design specimens and their controls; apply the new shell to copies.
for name in ['editor','request']:
    src=(root/(name+'-mockup.html')).read_text(encoding='utf-8')
    src=src.replace('</head>','<link rel="stylesheet" href="round9.css"><link rel="stylesheet" href="round9-workspace.css"></head>')
    src=re.sub(r'<header class="topbar">.*?</header>',nav,src,count=1,flags=re.S)
    for old,new in [('home-mockup.html','home9-mockup.html'),('skins-mockup.html','skins9-mockup.html'),('editor-mockup.html','editor9-mockup.html'),('request-mockup.html','request9-mockup.html')]:
        src=src.replace(old,new)
    src=src.replace('Customize your loadout','Customize your overlay').replace('Chat loadout','Your overlay').replace('Guild notice board','Request a skin')
    src=src.replace('Post a skin quest','Request a skin').replace('Post quest','Send request').replace('The next skin<br>starts with you.','What should chat<br>look like next?')
    (root/(name+'9-mockup.html')).write_text(src,encoding='utf-8')
print('Wrote Home, Skins, Docs and restyled Editor / Request design specimens')
